void Solver::rephase() {
    // Adaptive rephasing: adjust based on solver progress
    rephases = 0; // Reset counter for new rephasing cycle

    // Dynamically adjust threshold based on recent trail size variation
    if (trail.size() > threshold * 1.2) {
        // If trail has grown significantly, increase threshold more aggressively
        threshold *= 1.05;
    } else if (trail.size() < threshold * 0.8) {
        // If trail has shrunk, tighten threshold
        threshold *= 0.85;
    } else {
        // Default decay
        threshold *= 0.9;
    }

    // Adaptive rephase_limit scaling based on conflict rate
    double conflict_rate = (double)conflicts / (restarts > 0 ? restarts : 1);
    if (conflict_rate > 1000) {
        // High conflict rate: allow more rephases to escape local minima
        rephase_limit += 16384;
    } else if (conflict_rate < 100) {
        // Low conflict rate: be conservative with rephases
        rephase_limit += 4096;
    } else {
        // Moderate conflict rate: standard increment
        rephase_limit += 8192;
    }

    // Random perturbation to escape stagnation
    if (rand() % 100 < 20) {
        for (int i = 1; i <= vars; i++) {
            if (rand() % 100 < 30) {
                saved[i] = -saved[i]; // Flip some saved phases
            }
        }
    }

    // Update local_best based on current assignment if trail is non-empty
    if (!trail.empty()) {
        for (int i = 1; i <= vars; i++) {
            if (value[i] != 0) {
                local_best[i] = value[i];
            }
        }
    }
}
